MATCH (s1:Sculpture {name: "Bust of Victor Hugo"})-[:*]->(am:ArtMovement)
MATCH (s2:Sculpture {name: "The Cathedral"})-[:*]->(am)
RETURN am.name AS name, am.end_year AS end_year;

MATCH (p:Painting)
WHERE EXISTS {
  MATCH (p)-[:hasGenre]->(g:Genre)
  WHERE toLower(g.name) = 'portrait'
}
OR EXISTS {
  MATCH (p)-[:associatedWith]->(am:ArtMovement)
  WHERE toLower(am.name) CONTAINS 'academic'
}
RETURN count(DISTINCT p) AS paintingCount

MATCH (p:Painting)-[:displayedAt]->(m:Museum)
WHERE p.name IN ['Aglaida and Boniface', 'The Annunciation']
RETURN DISTINCT m.name AS museumName;

